function r(t){return`https://igotkarmayogi.gov.in/app/search?q=${encodeURIComponent(`MoSPI ${t}`)}&source=statiq_mospi`}async function a(t,s,n){try{const e=await fetch("/api/v1/igot/sync",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({user_parichay_id:t,assessment_id:s,scores:n,timestamp:new Date().toISOString()})});if(!e.ok)throw new Error(`Outbound sync failed with status ${e.status}`);const o=await e.json();return console.log("Outbound telemetry sync response:",o),!0}catch(e){return console.error("Failed to send assessment telemetry to iGOT:",e),!1}}export{r as g,a as s};
